-- Undo for 20261112210000_storage_own_prefix_policies.sql.
-- Restores the exact production storage.objects write policies (read from production pg_policies 2026-11-12, mirrored on staging).
-- WARNING: this restores the broad 'Authenticated users can upload ad assets' (any bucket) policy.
BEGIN;
DROP POLICY IF EXISTS "offer-logos own-prefix read" ON storage.objects;
DROP POLICY IF EXISTS "organic-posts own-prefix insert" ON storage.objects;
DROP POLICY IF EXISTS "organic-posts own-prefix update" ON storage.objects;
DROP POLICY IF EXISTS "organic-posts own-prefix delete" ON storage.objects;
DROP POLICY IF EXISTS "ad-ideas-assets own-prefix insert" ON storage.objects;
DROP POLICY IF EXISTS "ad-ideas-assets own-prefix update" ON storage.objects;
DROP POLICY IF EXISTS "ad-ideas-assets own-prefix delete" ON storage.objects;
DROP POLICY IF EXISTS "offer-logos own-prefix insert" ON storage.objects;
DROP POLICY IF EXISTS "offer-logos own-prefix update" ON storage.objects;
DROP POLICY IF EXISTS "offer-logos own-prefix delete" ON storage.objects;
DROP POLICY IF EXISTS "profile-images own-prefix insert" ON storage.objects;
DROP POLICY IF EXISTS "profile-images own-prefix update" ON storage.objects;
DROP POLICY IF EXISTS "profile-images own-prefix delete" ON storage.objects;
DROP POLICY IF EXISTS "business-creatives own-prefix insert" ON storage.objects;
DROP POLICY IF EXISTS "business-creatives own-prefix update" ON storage.objects;
DROP POLICY IF EXISTS "business-creatives own-prefix delete" ON storage.objects;
DROP POLICY IF EXISTS "avatars own-prefix insert" ON storage.objects;
DROP POLICY IF EXISTS "avatars own-prefix update" ON storage.objects;
DROP POLICY IF EXISTS "avatars own-prefix delete" ON storage.objects;
DROP POLICY IF EXISTS "shop-images own-prefix insert" ON storage.objects;
DROP POLICY IF EXISTS "shop-images own-prefix update" ON storage.objects;
DROP POLICY IF EXISTS "shop-images own-prefix delete" ON storage.objects;
DROP POLICY IF EXISTS "Allow ALL uploads to organic-posts" ON storage.objects;
CREATE POLICY "Allow ALL uploads to organic-posts" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((bucket_id = 'organic-posts'::text));
DROP POLICY IF EXISTS "Allow uploads to organic-posts" ON storage.objects;
CREATE POLICY "Allow uploads to organic-posts" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((bucket_id = 'organic-posts'::text));
DROP POLICY IF EXISTS "Users can upload organic-posts" ON storage.objects;
CREATE POLICY "Users can upload organic-posts" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((bucket_id = 'organic-posts'::text));
DROP POLICY IF EXISTS "Allow authenticated upload to organic-posts" ON storage.objects;
CREATE POLICY "Allow authenticated upload to organic-posts" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'organic-posts'::text) AND ((auth.uid() = owner) OR (owner IS NULL))));
DROP POLICY IF EXISTS "Allow authenticated upload to ad-ideas-assets" ON storage.objects;
CREATE POLICY "Allow authenticated upload to ad-ideas-assets" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'ad-ideas-assets'::text) AND (auth.role() = 'authenticated'::text)));
DROP POLICY IF EXISTS "Authenticated upload for offer logos" ON storage.objects;
CREATE POLICY "Authenticated upload for offer logos" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((bucket_id = 'offer-logos'::text));
DROP POLICY IF EXISTS "Authenticated upload for profile images" ON storage.objects;
CREATE POLICY "Authenticated upload for profile images" ON storage.objects AS PERMISSIVE FOR INSERT TO public WITH CHECK (((bucket_id = 'profile-images'::text) AND (auth.role() = 'authenticated'::text)));
DROP POLICY IF EXISTS "Authenticated users can upload ad assets" ON storage.objects;
CREATE POLICY "Authenticated users can upload ad assets" ON storage.objects AS PERMISSIVE FOR INSERT TO public WITH CHECK ((auth.role() = 'authenticated'::text));
DROP POLICY IF EXISTS "Business creatives authenticated insert" ON storage.objects;
CREATE POLICY "Business creatives authenticated insert" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((bucket_id = 'business-creatives'::text));
DROP POLICY IF EXISTS "Users can upload their own avatars" ON storage.objects;
CREATE POLICY "Users can upload their own avatars" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'avatars'::text) AND ((auth.uid())::text = "substring"(name, '^[^/]+'::text))));
DROP POLICY IF EXISTS "shop images write" ON storage.objects;
CREATE POLICY "shop images write" ON storage.objects AS PERMISSIVE FOR INSERT TO public WITH CHECK (((bucket_id = 'shop-images'::text) AND (auth.role() = 'authenticated'::text)));
DROP POLICY IF EXISTS "Allow authenticated update to ad-ideas-assets" ON storage.objects;
CREATE POLICY "Allow authenticated update to ad-ideas-assets" ON storage.objects AS PERMISSIVE FOR UPDATE TO authenticated USING (((bucket_id = 'ad-ideas-assets'::text) AND (auth.role() = 'authenticated'::text)));
DROP POLICY IF EXISTS "Authenticated update profile images" ON storage.objects;
CREATE POLICY "Authenticated update profile images" ON storage.objects AS PERMISSIVE FOR UPDATE TO public USING (((bucket_id = 'profile-images'::text) AND (auth.role() = 'authenticated'::text))) WITH CHECK ((bucket_id = 'profile-images'::text));
DROP POLICY IF EXISTS "Business creatives authenticated update" ON storage.objects;
CREATE POLICY "Business creatives authenticated update" ON storage.objects AS PERMISSIVE FOR UPDATE TO authenticated USING ((bucket_id = 'business-creatives'::text)) WITH CHECK ((bucket_id = 'business-creatives'::text));
DROP POLICY IF EXISTS "Users can update their own avatars" ON storage.objects;
CREATE POLICY "Users can update their own avatars" ON storage.objects AS PERMISSIVE FOR UPDATE TO authenticated USING (((bucket_id = 'avatars'::text) AND ((auth.uid())::text = "substring"(name, '^[^/]+'::text)))) WITH CHECK (((bucket_id = 'avatars'::text) AND ((auth.uid())::text = "substring"(name, '^[^/]+'::text))));
DROP POLICY IF EXISTS "shop images update" ON storage.objects;
CREATE POLICY "shop images update" ON storage.objects AS PERMISSIVE FOR UPDATE TO public USING (((bucket_id = 'shop-images'::text) AND (auth.role() = 'authenticated'::text))) WITH CHECK (((bucket_id = 'shop-images'::text) AND (auth.role() = 'authenticated'::text)));
DROP POLICY IF EXISTS "Allow authenticated delete from ad-ideas-assets" ON storage.objects;
CREATE POLICY "Allow authenticated delete from ad-ideas-assets" ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated USING (((bucket_id = 'ad-ideas-assets'::text) AND (auth.role() = 'authenticated'::text)));
DROP POLICY IF EXISTS "Authenticated delete profile images" ON storage.objects;
CREATE POLICY "Authenticated delete profile images" ON storage.objects AS PERMISSIVE FOR DELETE TO public USING (((bucket_id = 'profile-images'::text) AND (auth.role() = 'authenticated'::text)));
DROP POLICY IF EXISTS "Business creatives authenticated delete" ON storage.objects;
CREATE POLICY "Business creatives authenticated delete" ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated USING ((bucket_id = 'business-creatives'::text));
DROP POLICY IF EXISTS "Users can delete their own avatars" ON storage.objects;
CREATE POLICY "Users can delete their own avatars" ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated USING (((bucket_id = 'avatars'::text) AND ((auth.uid())::text = "substring"(name, '^[^/]+'::text))));
COMMIT;
